"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6084],{6084:a=>{a.exports=JSON.parse('{"slug":"rozhdaemost-rossiya-2025-demograficheskoe-eho","locale":"ru","title":"\u0412 \u0420\u043e\u0441\u0441\u0438\u0438 \u0432 2025 \u0433\u043e\u0434\u0443 \u0440\u043e\u0434\u0438\u043b\u043e\u0441\u044c \u043e\u043a\u043e\u043b\u043e 1,19 \u043c\u043b\u043d \u0434\u0435\u0442\u0435\u0439, \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 1999 \u0433\u043e\u0434\u0443","description":"\u0412 2025 \u0433\u043e\u0434\u0443 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0440\u043e\u0434\u0438\u043b\u043e\u0441\u044c \u043e\u043a\u043e\u043b\u043e 1,19 \u043c\u043b\u043d \u0434\u0435\u0442\u0435\u0439, \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 1999-\u043c. \u041f\u043e\u0447\u0435\u043c\u0443 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438 \u0447\u0442\u043e \u044d\u0442\u043e \u0437\u043d\u0430\u0447\u0438\u0442 \u0434\u043b\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442, \u043f\u0435\u043d\u0441\u0438\u0439 \u0438 \u043c\u0430\u0442\u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430.","blocks":[{"id":"b001","kind":"paragraph","text":"\u0412 2025 \u0433\u043e\u0434\u0443 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0440\u043e\u0434\u0438\u043b\u043e\u0441\u044c \u043e\u043a\u043e\u043b\u043e 1,19 \u043c\u043b\u043d \u0434\u0435\u0442\u0435\u0439. \u0420\u043e\u0441\u0441\u0442\u0430\u0442 \u0441 2024 \u0433\u043e\u0434\u0430 \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0438\u0445 \u0441\u0447\u0438\u0442\u0430\u044e\u0442 \u043a\u043e\u0441\u0432\u0435\u043d\u043d\u043e, \u043f\u043e \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0436\u0435\u043d\u0449\u0438\u043d \u0438 \u0440\u043e\u0436\u0434\u0430\u0435\u043c\u043e\u0441\u0442\u0438 \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435. \u0414\u0435\u043c\u043e\u0433\u0440\u0430\u0444 \u0410\u043b\u0435\u043a\u0441\u0435\u0439 \u0420\u0430\u043a\u0448\u0430 \u043f\u043e\u043b\u0443\u0447\u0438\u043b \u0431\u043b\u0438\u0437\u043a\u0443\u044e \u0446\u0438\u0444\u0440\u0443, 1,18 \u043c\u043b\u043d. \u042d\u0442\u043e \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 1999 \u0433\u043e\u0434\u0443, \u043a\u043e\u0433\u0434\u0430 \u0440\u043e\u0434\u0438\u043b\u043e\u0441\u044c 1,21 \u043c\u043b\u043d \u0434\u0435\u0442\u0435\u0439. \u0421\u043f\u0430\u0434 \u0438\u0434\u0451\u0442 10 \u043b\u0435\u0442 \u043f\u043e\u0434\u0440\u044f\u0434: \u0432 2015 \u0433\u043e\u0434\u0443 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u0431\u044b\u043b\u043e 1,94 \u043c\u043b\u043d, \u0432 2020-\u043c 1,44 \u043c\u043b\u043d, \u0432 2023-\u043c 1,26 \u043c\u043b\u043d."},{"id":"b002","kind":"paragraph","text":"\u0427\u0438\u0441\u043b\u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 2 \u0432\u0435\u0449\u0435\u0439: \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0435\u0442\u0435\u0439 \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u0440\u043e\u0436\u0430\u0435\u0442 \u043e\u0434\u043d\u0430 \u0436\u0435\u043d\u0449\u0438\u043d\u0430 \u0438 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0436\u0435\u043d\u0449\u0438\u043d \u0432 \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435, \u043a\u043e\u0433\u0434\u0430 \u043e\u0431\u044b\u0447\u043d\u043e \u0440\u043e\u0436\u0430\u044e\u0442. \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043c \u0448\u043a\u043e\u043b\u0443, \u0432 \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432 \u043a\u043e\u043d\u0446\u0435 1990-\u0445 \u043d\u0430\u0431\u0438\u0440\u0430\u043b\u0438 1 \u043f\u0435\u0440\u0432\u044b\u0439 \u043a\u043b\u0430\u0441\u0441 \u0432\u043c\u0435\u0441\u0442\u043e 2. \u0427\u0435\u0440\u0435\u0437 25–30 \u043b\u0435\u0442 \u044d\u0442\u0438 \u0434\u0435\u0442\u0438 \u0441\u0430\u043c\u0438 \u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c\u0438, \u0438 \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u043a\u0430\u0436\u0434\u0430\u044f \u0441\u0435\u043c\u044c\u044f \u0437\u0430\u0432\u0435\u0434\u0451\u0442 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435 \u0434\u0435\u0442\u0435\u0439, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u0445 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438, \u043f\u0435\u0440\u0432\u043e\u043a\u043b\u0430\u0441\u0441\u043d\u0438\u043a\u043e\u0432 \u0441\u043d\u043e\u0432\u0430 \u0431\u0443\u0434\u0435\u0442 \u043c\u0435\u043d\u044c\u0448\u0435. \u042d\u0442\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0434\u0435\u043c\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u044d\u0445\u043e\u043c. \u0416\u0435\u043d\u0449\u0438\u043d 15–49 \u043b\u0435\u0442 \u0432 2024 \u0433\u043e\u0434\u0443 \u0431\u044b\u043b\u043e 34,2 \u043c\u043b\u043d, \u0430 \u043a 2046 \u0433\u043e\u0434\u0443, \u043f\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0443 \u0420\u043e\u0441\u0441\u0442\u0430\u0442\u0430, \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f 27,4 \u043c\u043b\u043d, \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 20% \u043c\u0435\u043d\u044c\u0448\u0435."},{"id":"b003","kind":"paragraph","text":"\u0412\u0442\u043e\u0440\u0430\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430 \u0432 \u0442\u043e\u043c, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0435\u0442\u0435\u0439 \u0440\u043e\u0436\u0430\u0435\u0442 \u043a\u0430\u0436\u0434\u0430\u044f \u0436\u0435\u043d\u0449\u0438\u043d\u0430. \u0421\u0435\u0439\u0447\u0430\u0441 \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u043e\u043a\u043e\u043b\u043e 1,36, \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043a\u0430\u043a \u0432 \u0415\u0432\u0440\u043e\u0441\u043e\u044e\u0437\u0435 (1,34) \u0438 \u0413\u0435\u0440\u043c\u0430\u043d\u0438\u0438 (1,35). \u0427\u0442\u043e\u0431\u044b \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f \u0437\u0430\u043c\u0435\u0449\u0430\u043b\u0438 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430, \u043d\u0443\u0436\u043d\u043e \u043e\u043a\u043e\u043b\u043e 2,1. \u041f\u0440\u0438 1,36 \u043a\u0430\u0436\u0434\u043e\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0435 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u0442\u0440\u0435\u0442\u044c \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0433\u043e (1,36 / 2,1 ≈ 0,65). \u041d\u0430 \u0441\u0435\u043c\u0435\u0439\u043d\u0443\u044e \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0443 \u0420\u043e\u0441\u0441\u0438\u044f \u0432 2024 \u0433\u043e\u0434\u0443 \u0442\u0440\u0430\u0442\u0438\u043b\u0430 1,3% \u0412\u0412\u041f, \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u043f\u043e \u0441\u0442\u0440\u0430\u043d\u0430\u043c \u041e\u042d\u0421\u0420 \u0447\u0443\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435 2%."},{"id":"b004","kind":"paragraph","text":"\u0414\u043b\u044f \u0441\u0435\u043c\u0435\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 \u0432 \u0440\u0443\u0431\u043b\u044f\u0445 \u0434\u0435\u0448\u0435\u0432\u0435\u0435\u0442. \u0412 2016 \u0433\u043e\u0434\u0443 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u0434\u0430\u0432\u0430\u043b\u0438 \u043d\u0430 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430, 453 \u0442\u044b\u0441. \u0440\u0443\u0431\u043b\u0435\u0439, \u0438 \u043d\u0430 \u043d\u0435\u0433\u043e \u043c\u043e\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u043a\u0443\u043f\u0438\u0442\u044c \u043e\u043a\u043e\u043b\u043e 8,4 \u043a\u0432. \u043c \u0436\u0438\u043b\u044c\u044f. \u0412 2026 \u0433\u043e\u0434\u0443 \u0441\u0435\u043c\u044c\u044f, \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0449\u0430\u044f \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u043d\u0430 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 963 \u0442\u044b\u0441., \u0432 2,1 \u0440\u0430\u0437\u0430 \u0431\u043e\u043b\u044c\u0448\u0435, \u043d\u043e \u0436\u0438\u043b\u044c\u0451 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043b\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 3,4 \u0440\u0430\u0437\u0430, \u0438 \u044d\u0442\u043e \u043e\u043a\u043e\u043b\u043e 5,2 \u043a\u0432. \u043c. \u041a\u0430\u043f\u0438\u0442\u0430\u043b \u043d\u0430 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u043e\u043a\u043e\u043b\u043e 729 \u0442\u044b\u0441. \u0440\u0443\u0431\u043b\u0435\u0439, \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u0442 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 4 \u043a\u0432. \u043c. \u0421\u0435\u043c\u0435\u0439\u043d\u0430\u044f \u0438\u043f\u043e\u0442\u0435\u043a\u0430 \u0441 1 \u043e\u043a\u0442\u044f\u0431\u0440\u044f 2026 \u0433\u043e\u0434\u0430 \u0434\u043b\u044f \u0441\u0435\u043c\u044c\u0438 \u0441 1 \u0440\u0435\u0431\u0451\u043d\u043a\u043e\u043c \u0441\u0442\u043e\u0438\u0442 10–12% \u0432\u043c\u0435\u0441\u0442\u043e \u043f\u0440\u0435\u0436\u043d\u0438\u0445 6%."},{"id":"b005","kind":"paragraph","text":"\u041c\u0430\u043b\u043e \u0434\u0435\u0442\u0435\u0439 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0437\u043d\u0430\u0447\u0438\u0442 \u043c\u0430\u043b\u043e \u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 20 \u043b\u0435\u0442. \u042d\u043a\u043e\u043d\u043e\u043c\u0438\u0441\u0442 \u0420\u043e\u0441\u0442\u0438\u0441\u043b\u0430\u0432 \u041a\u0430\u043f\u0435\u043b\u044e\u0448\u043d\u0438\u043a\u043e\u0432 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u043a 2045 \u0433\u043e\u0434\u0443 \u0437\u0430\u043d\u044f\u0442\u044b\u0445 \u0441\u0442\u0430\u043d\u0435\u0442 \u043d\u0430 7 \u043c\u043b\u043d \u043c\u0435\u043d\u044c\u0448\u0435, \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u0441\u044f\u0442\u044b\u0439, \u0430 \u0432 \u043f\u043b\u043e\u0445\u043e\u043c \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0438 \u043d\u0430 10,5 \u043c\u043b\u043d. \u0420\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430\u043c \u044d\u0442\u043e \u0434\u0430\u0451\u0442 \u0441\u0438\u043b\u044c\u043d\u0443\u044e \u043f\u043e\u0437\u0438\u0446\u0438\u044e \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u0442\u0440\u0443\u0434\u0430: \u043b\u044e\u0434\u0435\u0439 \u043d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442, \u0438 \u0437\u0430 \u043d\u0438\u0445 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435. \u041d\u043e \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043f\u0435\u043d\u0441\u0438\u043e\u043d\u0435\u0440\u0430 \u0431\u0443\u0434\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043c\u0435\u043d\u044c\u0448\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0449\u0438\u0445, \u0430 \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u0430\u044f \u0431\u0430\u0437\u0430 \u0441\u043e\u0436\u043c\u0451\u0442\u0441\u044f."},{"id":"b006","kind":"paragraph","text":"\u0423 \u0441\u0435\u043c\u044c\u0438 \u0441 \u043d\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u043c \u043d\u0430 \u043c\u0430\u0442\u043a\u0430\u043f\u0438\u0442\u0430\u043b \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u043e\u0441\u0442\u043e\u0439: \u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441 \u0438\u043b\u0438 \u0436\u0434\u0430\u0442\u044c. \u0421 2016 \u0433\u043e\u0434\u0430 \u0436\u0438\u043b\u044c\u0451 \u0434\u043e\u0440\u043e\u0436\u0430\u043b\u043e \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u0438\u043d\u0434\u0435\u043a\u0441\u0430\u0446\u0438\u0438, \u0438 \u043a\u0430\u0436\u0434\u044b\u0439 \u0433\u043e\u0434 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u0441\u0442\u043e\u0438\u043b \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u043e\u0432. \u041a\u0430\u043f\u0438\u0442\u0430\u043b \u0438\u043d\u0434\u0435\u043a\u0441\u0438\u0440\u0443\u044e\u0442 \u043f\u043e \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043e\u0442\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0439 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u043a\u0443\u043f\u0438\u0442 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u0435\u0439\u0447\u0430\u0441, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0436\u0438\u043b\u044c\u0451 \u0431\u0443\u0434\u0435\u0442 \u0434\u043e\u0440\u043e\u0436\u0430\u0442\u044c \u043d\u0435 \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u043d\u0435\u0451. \u041a\u0430\u043a \u043f\u043e\u0432\u0435\u0434\u0443\u0442 \u0441\u0435\u0431\u044f \u0446\u0435\u043d\u044b, \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043e\u0431\u0435\u0449\u0430\u0435\u0442."},{"id":"b007","kind":"heading","text":"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0435\u0442\u0435\u0439 \u0440\u043e\u0434\u0438\u043b\u043e\u0441\u044c \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0432 2025 \u0433\u043e\u0434\u0443?"},{"id":"b008","kind":"paragraph","text":"\u041e\u043a\u043e\u043b\u043e 1,19 \u043c\u043b\u043d \u043f\u043e \u043a\u043e\u0441\u0432\u0435\u043d\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0435, \u0434\u0435\u043c\u043e\u0433\u0440\u0430\u0444 \u0410\u043b\u0435\u043a\u0441\u0435\u0439 \u0420\u0430\u043a\u0448\u0430 \u043d\u0430\u0441\u0447\u0438\u0442\u0430\u043b 1,18 \u043c\u043b\u043d. \u042d\u0442\u043e \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 1999 \u0433\u043e\u0434\u0443 (1,21 \u043c\u043b\u043d). \u0420\u043e\u0441\u0441\u0442\u0430\u0442 \u0441 2024 \u0433\u043e\u0434\u0430 \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0438\u0445 \u0441\u0447\u0438\u0442\u0430\u044e\u0442 \u043f\u043e \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0436\u0435\u043d\u0449\u0438\u043d \u0438 \u0440\u043e\u0436\u0434\u0430\u0435\u043c\u043e\u0441\u0442\u0438 \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435."},{"id":"b009","kind":"heading","text":"\u041f\u043e\u0447\u0435\u043c\u0443 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0440\u043e\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u0432\u0441\u0451 \u043c\u0435\u043d\u044c\u0448\u0435 \u0434\u0435\u0442\u0435\u0439?"},{"id":"b010","kind":"paragraph","text":"\u0421\u0445\u043e\u0434\u044f\u0442\u0441\u044f 2 \u043f\u0440\u0438\u0447\u0438\u043d\u044b. \u041a\u0430\u0436\u0434\u0430\u044f \u0436\u0435\u043d\u0449\u0438\u043d\u0430 \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u0440\u043e\u0436\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 1,36 \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u0430 \u0434\u043b\u044f \u0437\u0430\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0439 \u043d\u0443\u0436\u043d\u043e \u043e\u043a\u043e\u043b\u043e 2,1. \u0418 \u0441\u0430\u043c\u0438\u0445 \u0436\u0435\u043d\u0449\u0438\u043d \u0432 \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435, \u043a\u043e\u0433\u0434\u0430 \u043e\u0431\u044b\u0447\u043d\u043e \u0440\u043e\u0436\u0430\u044e\u0442, \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043c\u0435\u043d\u044c\u0448\u0435, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u043e\u043d\u0438 \u0440\u043e\u0434\u0438\u043b\u0438\u0441\u044c \u0432 \u043c\u0430\u043b\u043e\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 1990-\u0435."},{"id":"b011","kind":"heading","text":"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0436\u0438\u043b\u044c\u044f \u043c\u043e\u0436\u043d\u043e \u043a\u0443\u043f\u0438\u0442\u044c \u043d\u0430 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u0432 2026 \u0433\u043e\u0434\u0443?"},{"id":"b012","kind":"paragraph","text":"\u041e\u043a\u043e\u043b\u043e 963 \u0442\u044b\u0441. \u0440\u0443\u0431\u043b\u0435\u0439 \u043f\u0440\u0438 \u043f\u0435\u0440\u0432\u043e\u043c \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u0438 \u043d\u0430 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 5,2 \u043a\u0432. \u043c, \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430 \u043d\u0430 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u043e\u043a\u043e\u043b\u043e 729 \u0442\u044b\u0441., \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 4 \u043a\u0432. \u043c. \u0412 2016 \u0433\u043e\u0434\u0443 \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u0432 453 \u0442\u044b\u0441. \u0440\u0443\u0431\u043b\u0435\u0439 \u043f\u043e\u043a\u0443\u043f\u0430\u043b \u043e\u043a\u043e\u043b\u043e 8,4 \u043a\u0432. \u043c. \u0421 \u0442\u0435\u0445 \u043f\u043e\u0440 \u0441\u0443\u043c\u043c\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0432 2,1 \u0440\u0430\u0437\u0430, \u0430 \u0436\u0438\u043b\u044c\u0451 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043b\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 3,4 \u0440\u0430\u0437\u0430."}],"sources":[{"label":"\u0414\u0435\u043c\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u0440\u0438\u0437\u0438\u0441 \u0432\u0435\u0440\u043d\u0443\u043b\u0441\u044f. \u041d\u0430\u0441\u0435\u043b\u0435\u043d\u0438\u0435 \u0420\u043e\u0441\u0441\u0438\u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f","url":"https://thebell.io/demograficheskiy-krizis-vernulsya-naselenie-rossii-sokrashchaetsya--i-delo-ne-tolko-v-voyne-no-i-v-sistemnom-nedofinansirovanii-semeynoy-politiki"},{"label":"\u0420\u043e\u0441\u0441\u0438\u044f\u043d\u0430\u043c \u043d\u0430\u043f\u043e\u043c\u043d\u0438\u043b\u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u043c\u0430\u0442\u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430 \u043f\u043e\u0441\u043b\u0435 \u0438\u043d\u0434\u0435\u043a\u0441\u0430\u0446\u0438\u0438 \u0432 2026 \u0433\u043e\u0434\u0443","url":"https://www.rbc.ru/life/news/69ba3abc9a79474f38cf830b"}],"sourceBodySha256":"ff9748ccf2ba9fa76599dc66cba937d70782141706610d69e9984d278c697e19"}')}}]);